-- LLM-drafted translations (needs_review = TRUE throughout) of Level 6's
-- lesson content (seeded by migration 0037), into the 7 non-English
-- locales — same posture as migrations 0021, 0038-0041. This is the
-- final level; all six levels now have full translation coverage.
INSERT INTO lesson_translations (lesson_id, locale, title, content) VALUES
    ('00000000-0000-0000-0000-000000005101', 'pcm', 'Principles of Trauma-Informed Leadership', 'Trauma-informed leadership mean to recognize say the people wey you dey lead -- whether na manager, peer supporter, teacher, or community organizer -- fit dey carry experience wey you no fit see, and to adjust how you dey lead according to am. E no be say make you diagnose anybody or become their therapist; na to reduce unnecessary harm and create condition where people fit function and contribute.\n\nFour principles wey plenty people dey cite na: safety (body and emotional), trustworthiness and transparency (consistent, predictable communication), choice and collaboration (to involve people for decision wey dey affect dem instead of to impose on dem), and empowerment (to build on strength instead of to focus only on wetin dey missing).\n\nTo apply dis one no need special certificate. Small, consistent practice -- clear expectation, to follow through wetin you talk, to ask instead of assume -- go waka far to make space feel safer for everybody wey dey inside am, including people wey you no go ever sabi their history.'),
    ('00000000-0000-0000-0000-000000005101', 'yo', 'Àwọn Ìlànà Olórí Tí Ó Mọ̀ Nípa Ìpalára-Ọkàn', 'Olórí tí ó mọ̀ nípa ìpalára-ọkàn túmọ̀ sí mímọ̀ pé àwọn ènìyàn tí o ń darí -- yálà gẹ́gẹ́ bí alábòójútó, alátìlẹ́yìn ẹgbẹ́, olùkọ́, tàbí alábòójútó àwùjọ -- lè ní àwọn ìrírí tí o kò lè rí, kí o sì ṣe àtúnṣe bí o ṣe ń darí wọn gẹ́gẹ́ bí ó ti yẹ. Kì í ṣe láti ṣe àyẹ̀wò ẹnikẹ́ni tàbí láti di oníṣègùn wọn; ó jẹ́ láti dín ìpalára tí kò pọndandan kù àti láti dá àyíká tí àwọn ènìyàn lè ṣiṣẹ́ tí wọ́n sì lè ṣe àfikún síbẹ̀.\n\nÀwọn ìlànà mẹ́rin tí a sábà máa ń tọ́ka sí ni: àbò (ti ara àti ti ìmọ̀lára), ìgbẹ́kẹ̀lé àti ìṣípayá (ìbánisọ̀rọ̀ aṣepé, tí a lè sọ tẹ́lẹ̀), àṣàyàn àti ìfọwọ́sowọ́pọ̀ (láti fi àwọn ènìyàn kún inú ìpinnu tí ó ń kan wọn dípò kí a fipá mú wọn), àti agbára-fífún (láti kọ́ lórí agbára dípò kí a fi ojú sí àìtó nìkan).\n\nLílo àwọn wọ̀nyí kò nílò ẹ̀rí-ìmọ̀ pàtàkì. Àṣà kéékèèké, aṣepé -- ìfojúsọ́nà tí ó ṣe kedere, títẹ̀lé ohun tí o sọ, bíbéèrè dípò rírò -- máa ń lọ ọ̀nà jíjìn láti mú kí àyíká nímọ̀lára àbò sí i fún gbogbo ẹni tí ó wà níbẹ̀, pẹ̀lú àwọn ènìyàn tí o kò ní mọ̀ ìtàn wọn láé.'),
    ('00000000-0000-0000-0000-000000005101', 'ha', 'Ka''idojin Jagoranci Mai Fahimtar Rauni', 'Jagoranci mai fahimtar rauni yana nufin gane cewa mutanen da kake jagoranta -- ko a matsayin manaja, mai goyon bayan takwarori, malami, ko mai shirya al''umma -- na iya daukar abubuwan da ba za ka iya gani ba, da daidaita yadda kake jagoranta daidai da haka. Ba game da ganewar asali kowa ba ne ko zama likitan su; a maimakon haka, game da rage cutarwa marar bukata ne da kirkiro yanayi inda mutane za su iya aiki da bayarwa.\n\nKa''idoji guda hudu da aka saba ambatawa su ne: aminci (na jiki da na zuciya), amintacce da bayyana gaskiya (sadarwa tabbatacciya, mai hangowa), zabi da hadin kai (shigar da mutane cikin shawarwarin da suka shafe su maimakon tilasta musu), da karfafawa (ginawa a kan karfi maimakon mai da hankali kan rashi kadai).\n\nAiwatar da wadannan ba ya bukatar takaddun shaida na musamman. Kananan dabi''u masu dagewa -- tsammani bayyananne, bin abin da ka fada, tambaya maimakon zato -- suna taimakawa sosai wajen sa wuri ya ji aminci ga kowa a cikinsa, har da mutanen da ba za ka taba sanin tarihinsu ba.'),
    ('00000000-0000-0000-0000-000000005101', 'ig', 'Ụkpụrụ Ndu Nke Na-Aghọta Mmerụ Ahụ-Mmụọ', 'Ndu na-aghọta mmerụ ahụ-mmụọ pụtara ịmata na ndị ị na-edu -- ma ọ bụ dị ka onye njikwa, onye nkwado ibe, onye nkuzi, ma ọ bụ onye nhazi obodo -- nwere ike ibu ahụmịhe ị na-apụghị ịhụ anya, na ịgbanwe otú ị si edu ha dịka o kwesịrị. Ọ bụghị banyere ịchọpụta onye ọ bụla ọrịa ya ma ọ bụ ịghọ dọkịta ha; ọ bụ banyere ibelata mmerụ na-adịghị mkpa na ịmepụta ọnọdụ ebe ndị mmadụ nwere ike ịrụ ọrụ ma tinye aka.\n\nỤkpụrụ anọ a na-akpọkarị bụ: nchekwa (nke anụ ahụ na nke mmetụta), ntụkwasị obi na ikpughe ihe (nkwukọrịta na-adịgide adịgide, nke a pụrụ ibu amụma), nhọrọ na mmekọrịta (itinye ndị mmadụ n''ime mkpebi ndị metụtara ha karịa imanye ha), na inye ike (iwuli n''elu ike karịa ilekwasị anya naanị n''ihe na-efu).\n\nItinye ndị a n''ọrụ anaghị achọ akwụkwọ ebe akaebe pụrụ iche. Obere omume na-adịgide adịgide -- atụmanya doro anya, ime ihe ị kwuru, ịjụ karịa iche n''echiche -- na-eme nnukwu ihe n''ime ime ka ohere ahụ dị nchekwa karịa nye onye ọ bụla nọ n''ime ya, gụnyere ndị ị na-agaghị amata akụkọ ndụ ha.'),
    ('00000000-0000-0000-0000-000000005101', 'fr', 'Principes du Leadership Tenant Compte du Traumatisme', 'Le leadership tenant compte du traumatisme signifie reconnaître que les personnes que vous dirigez -- que ce soit en tant que manager, soutien par les pairs, enseignant, ou organisateur communautaire -- peuvent porter des expériences que vous ne pouvez pas voir, et ajuster votre façon de diriger en conséquence. Il ne s''agit pas de diagnostiquer qui que ce soit ni de devenir son thérapeute ; il s''agit de réduire les préjudices inutiles et de créer des conditions où les gens peuvent fonctionner et contribuer.\n\nQuatre principes largement cités sont : la sécurité (physique et émotionnelle), la fiabilité et la transparence (une communication cohérente et prévisible), le choix et la collaboration (impliquer les gens dans les décisions qui les affectent plutôt que de les leur imposer), et l''autonomisation (s''appuyer sur les forces plutôt que de se concentrer uniquement sur les manques).\n\nAppliquer ces principes ne nécessite pas de qualifications spéciales. Des pratiques modestes et cohérentes -- des attentes claires, tenir parole, demander plutôt que supposer -- contribuent grandement à rendre un espace plus sûr pour tous ceux qui s''y trouvent, y compris les personnes dont vous ne connaîtrez jamais l''histoire.'),
    ('00000000-0000-0000-0000-000000005101', 'sw', 'Kanuni za Uongozi Unaozingatia Kiwewe', 'Uongozi unaozingatia kiwewe unamaanisha kutambua kuwa watu unaowaongoza -- iwe kama meneja, msaidizi wa rika, mwalimu, au mratibu wa jamii -- huenda wakiwa na uzoefu usioonekana kwako, na kurekebisha jinsi unavyoongoza ipasavyo. Si kuhusu kumchunguza mtu yeyote wala kuwa mtaalamu wake wa matibabu; ni kuhusu kupunguza madhara yasiyo ya lazima na kuunda hali ambazo watu wanaweza kufanya kazi na kuchangia.\n\nKanuni nne zinazotajwa sana ni: usalama (wa kimwili na kihisia), kuaminika na uwazi (mawasiliano thabiti, yanayotabirika), hiari na ushirikiano (kuwashirikisha watu katika maamuzi yanayowahusu badala ya kuwalazimisha), na uwezeshaji (kujenga juu ya nguvu badala ya kuzingatia upungufu pekee).\n\nKutumia haya hakuhitaji vyeti maalum. Mazoea madogo, thabiti -- matarajio wazi, kutekeleza unachosema, kuuliza badala ya kudhani -- husaidia sana kufanya nafasi ihisi salama zaidi kwa kila mtu aliyemo, ikiwemo watu ambao hutawahi kujua historia yao.'),
    ('00000000-0000-0000-0000-000000005101', 'ar', 'مبادئ القيادة المراعية للصدمة', 'تعني القيادة المراعية للصدمة إدراك أن الأشخاص الذين تقودهم -- سواء كمدير، أو داعم أقران، أو معلم، أو منظم مجتمعي -- قد يحملون تجارب لا يمكنك رؤيتها، وتعديل طريقة قيادتك وفقًا لذلك. الأمر لا يتعلق بتشخيص أي شخص أو أن تصبح معالجه؛ بل يتعلق بتقليل الضرر غير الضروري وخلق ظروف يمكن للناس فيها العمل والمساهمة.\n\nمن المبادئ الأربعة الشائعة الاقتباس: الأمان (الجسدي والعاطفي)، الجدارة بالثقة والشفافية (تواصل متسق يمكن التنبؤ به)، الاختيار والتعاون (إشراك الناس في القرارات التي تؤثر عليهم بدلاً من فرضها)، والتمكين (البناء على نقاط القوة بدلاً من التركيز فقط على أوجه القصور).\n\nتطبيق هذه المبادئ لا يتطلب مؤهلات خاصة. الممارسات الصغيرة والمتسقة -- توقعات واضحة، الوفاء بما تقوله، السؤال بدلاً من الافتراض -- تقطع شوطًا طويلاً نحو جعل المكان يبدو أكثر أمانًا للجميع فيه، بمن فيهم أشخاص لن تعرف تاريخهم أبدًا.'),

    ('00000000-0000-0000-0000-000000005102', 'pcm', 'How To Support Others Without To Overstep', 'To support person wey don experience trauma different from to treat am. Peer and informal support dey valuable exactly because e dey offer connection and understanding -- e no be clinical intervention. To know dat difference, and where your role dey end, dey protect both you and the person wey you dey support.\n\nSupport wey useful often dey look like to listen without trying to fix, to believe wetin person share without to demand detail or proof, and no to pressure anybody make dem "move on" for timeline wey suit you instead of dem. E also mean to recognize when situation pass wetin peer support fit safely address, and to know how to point person towards professional help without to abandon dem for the process.\n\nTo overstep -- to give advice as if na clinical guidance, to push person make dem share more pass wetin dem ready for, or to carry responsibility for another person healing -- fit cause real harm, even with good intention. Good support dey hold space; e no dey take over.'),
    ('00000000-0000-0000-0000-000000005102', 'yo', 'Bí A Ṣe Ń Ṣe Àtìlẹ́yìn Fún Àwọn Mìíràn Láì Kọjá Ààlà', 'Ṣíṣe àtìlẹ́yìn fún ẹni tí ó ti ní ìrírí ìpalára-ọkàn yàtọ̀ sí ìtọ́jú wọn. Àtìlẹ́yìn ẹgbẹ́ àti àìjẹ́-oníṣe-ìlànà níye lórí gan-an nítorí pé ó ń fúnni ní ìsopọ̀ àti òye -- kì í ṣe ìdásí ìṣègùn. Mímọ̀ ìyàtọ̀ yẹn, àti ibi tí ipa rẹ dópin sí, ń dáàbò bo ìwọ àti ẹni tí o ń ṣe àtìlẹ́yìn fún.\n\nÀtìlẹ́yìn tí ó wúlò sábà máa ń dà bí gbígbọ́ láì gbìyànjú láti tún un ṣe, gbígba ohun tí ẹnìkan bá fi sọ gbọ́ láì béèrè kúlẹ̀kúlẹ̀ tàbí ẹ̀rí, àti àìfipá mú ẹnikẹ́ni láti "tẹ̀síwájú" ní àkókò tí ó bá ọ mu dípò wọn. Ó tún túmọ̀ sí mímọ̀ ìgbà tí ipò kan bá kọjá ohun tí àtìlẹ́yìn ẹgbẹ́ lè fi ààbò kojú, àti mímọ̀ bí a ṣe ń tọ́ka ẹnìkan sí ìrànlọ́wọ́ ògbógi láì fi wọ́n sílẹ̀ nínú ìlànà náà.\n\nKíkọjá ààlà -- fífún ní ìmọ̀ràn bí ẹni pé ó jẹ́ ìtọ́ni ìṣègùn, kíkọ́ ẹnìkan láti sọ ohun púpọ̀ ju bí wọ́n ṣe múra sílẹ̀ tó, tàbí gbígba ojúṣe fún ìmúpadàbọ̀sípò ẹlòmíràn -- lè fa ìpalára gidi, kódà pẹ̀lú èrò rere. Àtìlẹ́yìn rere ń di àyè mú; kò gba ipò gbogbo.'),
    ('00000000-0000-0000-0000-000000005102', 'ha', 'Goyon Bayan Wasu Ba Tare Da Wuce Iyaka Ba', 'Goyon bayan wanda ya samu rauni ya bambanta da maganinsa. Goyon bayan takwarori da na yau da kullum na da daraja domin su ne suke bayar da hadin kai da fahimta -- ba su ba shiga tsakani na asibiti ba. Sanin wannan bambanci, da inda rawar ka ke karewa, yana kiyaye kai da mutumin da kake taimakawa.\n\nGoyon baya mai amfani galibi yana kama da sauraro ba tare da kokarin gyarawa ba, yarda da abin da wani ya raba ba tare da bukatar bayani ko hujja ba, da rashin matsa wa kowa su "ci gaba" a kan jadawalin da ya dace da kai maimakon su. Haka kuma yana nufin gane lokacin da wani yanayi ya wuce abin da goyon bayan takwarori zai iya magance shi lafiya, da sanin yadda za a nuna wa wani zuwa taimakon kwararru ba tare da yin watsi da su a cikin tsarin ba.\n\nWucewa iyaka -- bayar da shawara kamar dai jagorar asibiti ce, matsa wa wani ya raba fiye da yadda yake shirye, ko daukar nauyin warkar da wani -- na iya haifar da cutarwa ta ainihi, ko da da nufin kyau. Goyon baya mai kyau yana rike sarari; ba ya karbe shi."'),
    ('00000000-0000-0000-0000-000000005102', 'ig', 'Ịkwado Ndị Ọzọ Ma Na-Agafeghị Oke', 'Ikwado onye nwetara mmerụ ahụ-mmụọ dị iche na ịgwọ ya. Nkwado ibe na nke na-abụghị nke ọrụ dị oke mkpa n''ihi na ọ na-enye njikọ na nghọta -- ọ bụghị ọgwụgwọ ahụike. Ịma ọdịiche ahụ, na ebe ọrụ gị kwụsịrị, na-echebe gị na onye ị na-akwado.\n\nNkwado bara uru na-adịkarị ka ige ntị na-anwaghị idozi, ikwere ihe onye kọrọ na-arịọghị nkọwa ma ọ bụ ihe akaebe, na ịnarịghị amanye onye ọ bụla "ịga n''ihu" n''oge kwesịrị gị karịa ha. Ọ pụtakwara ịmata mgbe ọnọdụ gafere ihe nkwado ibe nwere ike idozi n''enweghị ihe ize ndụ, na ịma otú e si atụziri onye ihu n''ebe enyemaka ọkachamara dị n''enweghị ihapụ ya n''usoro ahụ.\n\nịgafe oke -- inye ndụmọdụ dị ka à ga-asị na ọ bụ ntuziaka ahụike, ịkwagide onye ka ọ kọọ karịa ka ha dịla njikere, ma ọ bụ iburu ibu ọrụ maka ọgwụgwọ onye ọzọ -- nwere ike ịkpata ezi mmerụ, ọbụlagodi na ezi ebumnuche. Ezi nkwado na-ejide oghere; ọ naghị anara ya ọnọdụ.'),
    ('00000000-0000-0000-0000-000000005102', 'fr', 'Soutenir les Autres Sans Outrepasser Son Rôle', 'Soutenir quelqu''un ayant vécu un traumatisme est différent de le traiter. Le soutien par les pairs et informel est précieux précisément parce qu''il offre connexion et compréhension -- pas une intervention clinique. Connaître cette distinction, et où votre rôle s''arrête, vous protège ainsi que la personne que vous soutenez.\n\nUn soutien utile ressemble souvent à écouter sans essayer de réparer, croire ce que quelqu''un partage sans exiger de détails ou de preuves, et ne pas pousser quelqu''un à « passer à autre chose » selon un calendrier qui vous convient plutôt qu''à lui. Cela signifie aussi reconnaître quand une situation dépasse ce que le soutien par les pairs peut aborder en toute sécurité, et savoir orienter quelqu''un vers une aide professionnelle sans l''abandonner dans ce processus.\n\nOutrepasser son rôle -- donner des conseils comme s''il s''agissait d''orientations cliniques, pousser quelqu''un à partager plus qu''il n''est prêt à le faire, ou endosser la responsabilité de la guérison de quelqu''un d''autre -- peut causer un réel préjudice, même avec de bonnes intentions. Un bon soutien tient l''espace ; il ne prend pas le contrôle.'),
    ('00000000-0000-0000-0000-000000005102', 'sw', 'Kusaidia Wengine Bila Kuvuka Mpaka', 'Kusaidia mtu aliyepitia kiwewe ni tofauti na kumtibu. Msaada wa rika na usio rasmi una thamani haswa kwa sababu hutoa muunganiko na uelewa -- si uingiliaji wa kimatibabu. Kujua tofauti hiyo, na mahali jukumu lako linapoishia, hulinda wewe na mtu unayemsaidia.\n\nMsaada wenye manufaa mara nyingi huonekana kama kusikiliza bila kujaribu kurekebisha, kuamini kile mtu anachoshiriki bila kudai maelezo au uthibitisho, na kutomsukuma mtu yeyote "kuendelea mbele" kwa ratiba inayokufaa wewe badala yake. Pia inamaanisha kutambua wakati hali inazidi kile msaada wa rika unaweza kushughulikia kwa usalama, na kujua jinsi ya kumwelekeza mtu kwenye msaada wa kitaalamu bila kumwacha katika mchakato huo.\n\nKuvuka mpaka -- kutoa ushauri kana kwamba ni mwongozo wa kimatibabu, kumsukuma mtu ashiriki zaidi ya alivyo tayari, au kuchukua jukumu la uponyaji wa mtu mwingine -- kunaweza kusababisha madhara halisi, hata kwa nia njema. Msaada mzuri hushikilia nafasi; haushiki udhibiti.'),
    ('00000000-0000-0000-0000-000000005102', 'ar', 'دعم الآخرين دون تجاوز الحدود', 'دعم شخص مر بصدمة يختلف عن علاجه. الدعم من الأقران وغير الرسمي ذو قيمة بالتحديد لأنه يقدم التواصل والتفهم -- وليس تدخلاً سريريًا. معرفة هذا التمييز، وأين ينتهي دورك، يحميك أنت والشخص الذي تدعمه.\n\nالدعم المفيد غالبًا ما يبدو كالاستماع دون محاولة الإصلاح، وتصديق ما يشاركه شخص ما دون المطالبة بتفاصيل أو إثبات، وعدم الضغط على أي شخص "للمضي قدمًا" وفق جدول زمني يناسبك أنت لا هو. يعني أيضًا إدراك متى يتجاوز الموقف ما يمكن لدعم الأقران معالجته بأمان، ومعرفة كيفية توجيه شخص ما نحو المساعدة المتخصصة دون التخلي عنه في هذه العملية.\n\nتجاوز الحدود -- تقديم نصيحة وكأنها توجيه سريري، دفع شخص ما للمشاركة أكثر مما هو مستعد له، أو تحمل مسؤولية شفاء شخص آخر -- يمكن أن يسبب ضررًا حقيقيًا، حتى بنوايا حسنة. الدعم الجيد يحفظ المساحة؛ لا يسيطر عليها.'),

    ('00000000-0000-0000-0000-000000005103', 'pcm', 'How To Sustain Yourself While You Dey Support Others', 'To support people through hard experience, whether formally or informally, get real cost if you no dey take care of yourself too. Vicarious or secondary trauma -- to absorb distress from to hear about another person hard experience repeatedly -- na risk wey dem don recognize for caregivers, peer supporters, and leaders alike, e no be sign say you no fit do the role.\n\nSupport wey go last need the same regulation and awareness practice wey we don cover before for dis course, wey you go apply to yourself: to notice your own capacity, to set boundary around wetin you dey take on, and to get your own source of support instead of to just be source of support for others only.\n\nThere no be version of dis work wey go last without rest and limit. To protect your own capacity no be selfish or failure of commitment -- na wetin dey allow you continue to show up for others without to burn out or to cause harm through depletion.'),
    ('00000000-0000-0000-0000-000000005103', 'yo', 'Bí A Ṣe Ń Pa Ara Ẹni Mọ́ Nígbà Tí A Bá Ń Ṣe Àtìlẹ́yìn Fún Àwọn Mìíràn', 'Ṣíṣe àtìlẹ́yìn fún àwọn ènìyàn láàrin ìrírí tí ó le, yálà ní ọ̀nà ìlànà tàbí tí kò ní ìlànà, ní iye owó gidi tí o kò bá tọ́jú ara rẹ pẹ̀lú. Ìpalára-ọkàn aṣojú tàbí kejì -- gbígba másùnmáwo látinú gbígbọ́ nípa ìrírí tí ó le ti ẹlòmíràn léraléra -- jẹ́ ewu tí a mọ̀ fún àwọn olùtọ́jú, àwọn alátìlẹ́yìn ẹgbẹ́, àti àwọn olórí bákan náà, kì í ṣe àmì pé o kò yẹ fún ipò náà.\n\nÀtìlẹ́yìn tí yóò fi ìdúró múlẹ̀ nílò àwọn àṣàrò ìṣàtúnṣe àti ìmọ̀ ara-ẹni kan náà tí a ti sọ̀rọ̀ nípa rẹ̀ ṣáájú nínú ẹ̀kọ́ yìí, tí a óò lò sí ara rẹ fúnra rẹ: ṣíṣàkíyèsí agbára ara rẹ, ṣíṣètò àwọn òpin yí ohun tí o ń gbà kalẹ̀ ká, àti níní orísun àtìlẹ́yìn tirẹ dípò kí ó jẹ́ orísun àtìlẹ́yìn fún àwọn ẹlòmíràn nìkan.\n\nKò sí ẹ̀yà iṣẹ́ yìí tí yóò fi ìdúró múlẹ̀ láì sí ìsinmi àti òpin. Dídáàbò bo agbára ara ẹni kì í ṣe amọtara-ẹni-nìkan tàbí àṣìṣe ìfaramọ́ -- ó jẹ́ ohun tí ó jẹ́ kí o lè máa bá a lọ láti farahàn fún àwọn mìíràn láì jóná tàbí láti fa ìpalára nípasẹ̀ àìlera.'),
    ('00000000-0000-0000-0000-000000005103', 'ha', 'Kiyaye Kanka Yayin Goyon Bayan Wasu', 'Goyon bayan mutane ta cikin gogewa masu wuya, ko a hukumance ko ba a hukumance ba, yana da ainihin tsada idan ba ka kuma kula da kanka ba. Rauni na kaikaice ko na biyu -- daukar damuwa daga jin maimaita labarin gogewa masu wuya na wasu -- hadari ne da aka sani ga masu kulawa, masu goyon bayan takwarori, da shugabanni daidai, ba alamar cewa ba ka dace da rawar ba.\n\nGoyon baya mai dorewa yana bukatar irin dabarun daidaitawa da wayewar kai da aka tattauna a baya a cikin wannan darasi, da za a yi amfani da su a kanka: lura da karfinka, kayyade iyakoki kan abin da kake dauka, da samun tushen goyon bayanka na kanka maimakon kasancewa tushen goyon baya ga wasu kadai.\n\nBabu wani sigar wannan aiki da zai dore ba tare da hutawa da iyaka ba. Kiyaye karfinka ba son kai ba ne ko gazawar sadaukarwa -- shi ne abin da ke bada dama ka ci gaba da nunawa ga wasu ba tare da kona kanka ko haddasa cutarwa ta hanyar karewa ba.'),
    ('00000000-0000-0000-0000-000000005103', 'ig', 'Idowe Onwe Gị Mgbe Ị Na-Akwado Ndị Ọzọ', 'Ikwado ndị mmadụ site n''ahụmịhe siri ike, ma ọ bụ n''usoro ma ọ bụ na-abụghị n''usoro, nwere ezigbo ọnụ ahịa ma ọ bụrụ na ị naghị elekọtakwa onwe gị. Mmerụ ahụ-mmụọ nnọchianya ma ọ bụ nke abụọ -- ịnata mwute site n''ịnụkarị maka ahụmịhe siri ike nke ndị ọzọ -- bụ ihe ize ndụ amatara nye ndị na-elekọta, ndị nkwado ibe, na ndị ndu niile, ọ bụghị ihe ngosi na ị dabaghị maka ọrụ ahụ.\n\nNkwado ga-adịgide achọ otu omume nhazi na ịmara onwe e kwuru na mbụ n''ime nkuzi a, nke a ga-etinye n''onwe gị: ịmata ikike onwe gị, ịtọ oke gburugburu ihe ị na-ewere, na inwe isi mmalite nkwado nke gị karịa ịbụ naanị isi mmalite nkwado nye ndị ọzọ.\n\nỌ dịghị ụdị ọrụ a ga-adịgide n''enweghị izu ike na oke. Ichekwa ikike onwe gị abụghị ịhụ naanị onwe gị n''anya ma ọ bụ ọdịda nrara onwe -- ọ bụ ihe na-eme ka ị nwee ike ịnọgide na-apụta ihu nye ndị ọzọ n''amụghị ọkụ ma ọ bụ ikpata mmerụ site n''ọgbaghara.'),
    ('00000000-0000-0000-0000-000000005103', 'fr', 'Se Préserver Tout en Soutenant les Autres', 'Soutenir des personnes à travers des expériences difficiles, que ce soit formellement ou informellement, a un coût réel si vous ne prenez pas également soin de vous-même. Le traumatisme vicariant ou secondaire -- absorber la détresse en entendant à plusieurs reprises parler des expériences difficiles d''autrui -- est un risque reconnu pour les aidants, les soutiens par les pairs et les dirigeants de la même manière, pas un signe que vous n''êtes pas fait pour ce rôle.\n\nUn soutien durable nécessite les mêmes pratiques de régulation et de conscience de soi abordées plus tôt dans ce cours, appliquées à vous-même : remarquer votre propre capacité, poser des limites autour de ce que vous prenez en charge, et avoir vos propres sources de soutien plutôt que d''être uniquement une source de soutien pour les autres.\n\nIl n''existe aucune version de ce travail qui soit durable sans repos ni limites. Protéger sa propre capacité n''est ni égoïste ni un manque d''engagement -- c''est ce qui vous permet de continuer à être présent pour les autres sans vous épuiser ni causer de tort par épuisement.'),
    ('00000000-0000-0000-0000-000000005103', 'sw', 'Kujihifadhi Wakati Unasaidia Wengine', 'Kusaidia watu kupitia uzoefu mgumu, rasmi au isiyo rasmi, kuna gharama halisi kama hujijali pia wewe mwenyewe. Kiwewe cha mfano au cha pili -- kunyonya dhiki kutokana na kusikia mara kwa mara kuhusu uzoefu mgumu wa wengine -- ni hatari inayotambulika kwa walezi, wasaidizi wa rika, na viongozi sawa, si ishara kuwa hufai kwa jukumu hilo.\n\nMsaada endelevu unahitaji mazoezi yaleyale ya udhibiti na kujitambua yaliyoshughulikiwa mapema katika kozi hii, yanayotumika kwako mwenyewe: kutambua uwezo wako mwenyewe, kuweka mipaka kuhusu unachobeba, na kuwa na vyanzo vyako mwenyewe vya msaada badala ya kuwa chanzo cha msaada kwa wengine pekee.\n\nHakuna aina ya kazi hii inayoweza kuendelea bila kupumzika na mipaka. Kulinda uwezo wako mwenyewe si ubinafsi wala kushindwa kujitolea -- ni kinachokuwezesha kuendelea kujitokeza kwa wengine bila kuchoka kupita kiasi au kusababisha madhara kwa kujimaliza.'),
    ('00000000-0000-0000-0000-000000005103', 'ar', 'الحفاظ على نفسك أثناء دعم الآخرين', 'دعم الناس خلال التجارب الصعبة، رسميًا أو بشكل غير رسمي، له تكلفة حقيقية إذا لم تعتنِ بنفسك أيضًا. الصدمة بالوكالة أو الثانوية -- استيعاب الضيق من سماع تجارب الآخرين الصعبة بشكل متكرر -- خطر معروف لمقدمي الرعاية وداعمي الأقران والقادة على حد سواء، وليس علامة على عدم ملاءمتك للدور.\n\nيتطلب الدعم المستدام نفس ممارسات التنظيم والوعي التي تم تناولها سابقًا في هذه الدورة، مطبقة على نفسك: ملاحظة قدرتك الخاصة، وضع حدود حول ما تتحمله، وامتلاك مصادر دعمك الخاصة بدلاً من أن تكون مصدر دعم للآخرين فقط.\n\nلا توجد نسخة من هذا العمل مستدامة دون راحة وحدود. حماية قدرتك الخاصة ليست أنانية أو فشلاً في الالتزام -- إنها ما يسمح لك بالاستمرار في التواجد للآخرين دون الاحتراق أو التسبب بضرر من خلال الاستنزاف.');

INSERT INTO quiz_question_translations (question_id, locale, text) VALUES
    ('00000000-0000-0000-0000-000000005301', 'pcm', 'Which one of dis na one of the four trauma-informed leadership principles wey dis lesson talk about?'),
    ('00000000-0000-0000-0000-000000005301', 'yo', 'Èwo lára àwọn wọ̀nyí ni ọ̀kan lára àwọn ìlànà olórí mẹ́rin tí ó mọ̀ nípa ìpalára-ọkàn tí a ṣàpèjúwe nínú ẹ̀kọ́ yìí?'),
    ('00000000-0000-0000-0000-000000005301', 'ha', 'Wane daga cikin wadannan yana daya daga cikin ka''idojin jagoranci mai fahimtar rauni guda hudu da aka bayyana a wannan darasi?'),
    ('00000000-0000-0000-0000-000000005301', 'ig', 'Kedu nke n''ime ndị a bụ otu n''ime ụkpụrụ ndu anọ na-aghọta mmerụ ahụ-mmụọ nkuzi a kọwara?'),
    ('00000000-0000-0000-0000-000000005301', 'fr', 'Lequel de ces éléments est l''un des quatre principes de leadership tenant compte du traumatisme décrits dans cette leçon ?'),
    ('00000000-0000-0000-0000-000000005301', 'sw', 'Ni ipi kati ya haya ni mojawapo ya kanuni nne za uongozi unaozingatia kiwewe zilizoelezwa katika somo hili?'),
    ('00000000-0000-0000-0000-000000005301', 'ar', 'أي من هذه واحد من مبادئ القيادة الأربعة المراعية للصدمة الموصوفة في هذا الدرس؟'),

    ('00000000-0000-0000-0000-000000005302', 'pcm', 'Wetin be example of "to overstep" when you dey support person, according to dis lesson?'),
    ('00000000-0000-0000-0000-000000005302', 'yo', 'Kí ni àpẹẹrẹ "kíkọjá ààlà" nígbà tí a bá ń ṣe àtìlẹ́yìn fún ẹnìkan, gẹ́gẹ́ bí ẹ̀kọ́ yìí ṣe sọ?'),
    ('00000000-0000-0000-0000-000000005302', 'ha', 'Mene ne misalin "wuce iyaka" yayin goyon bayan wani, bisa ga wannan darasi?'),
    ('00000000-0000-0000-0000-000000005302', 'ig', 'Gịnị bụ ihe atụ nke "ịgafe oke" mgbe ị na-akwado onye, dịka nkuzi a kwuru?'),
    ('00000000-0000-0000-0000-000000005302', 'fr', 'Qu''est-ce qu''un exemple de « dépassement de rôle » lorsqu''on soutient quelqu''un, selon cette leçon ?'),
    ('00000000-0000-0000-0000-000000005302', 'sw', 'Ni mfano gani wa "kuvuka mpaka" unaposaidia mtu, kulingana na somo hili?'),
    ('00000000-0000-0000-0000-000000005302', 'ar', 'ما مثال "تجاوز الحدود" عند دعم شخص ما، وفقًا لهذا الدرس؟'),

    ('00000000-0000-0000-0000-000000005303', 'pcm', 'Wetin dis lesson call the risk of to absorb distress from to support others repeatedly?'),
    ('00000000-0000-0000-0000-000000005303', 'yo', 'Kí ni ẹ̀kọ́ yìí pè ewu gbígba másùnmáwo látinú ṣíṣe àtìlẹ́yìn fún àwọn mìíràn léraléra?'),
    ('00000000-0000-0000-0000-000000005303', 'ha', 'Mece ce wannan darasi ya kira hadarin daukar damuwa daga goyon bayan wasu akai-akai?'),
    ('00000000-0000-0000-0000-000000005303', 'ig', 'Gịnị ka nkuzi a kpọrọ ihe ize ndụ nke ịnata mwute site n''ịkwado ndị ọzọ mgbe mgbe?'),
    ('00000000-0000-0000-0000-000000005303', 'fr', 'Comment cette leçon nomme-t-elle le risque d''absorber la détresse en soutenant les autres de façon répétée ?'),
    ('00000000-0000-0000-0000-000000005303', 'sw', 'Somo hili linaita nini hatari ya kunyonya dhiki kutokana na kuwasaidia wengine mara kwa mara?'),
    ('00000000-0000-0000-0000-000000005303', 'ar', 'ماذا يسمي هذا الدرس خطر استيعاب الضيق من دعم الآخرين بشكل متكرر؟');

